// Package behaviour reproduces SEONBehaviourProbe's sensor-aggregation pipeline
// so fingerprints generated by this SDK carry a realistic `behaviour_results`
// block even when no real CoreMotion / CoreLocation hardware is available.
//
// The output of Simulate is byte-shape-identical to what
// -[SEONBehaviourProbe stopBehaviourMonitoring] (IDA 0x1300c) emits on a real
// iPhone after a window of CMDeviceMotion + CMMagnetometer + CLHeading
// collection. See docs/behaviour.md for the full field map, IDA addresses,
// orientation table, and at-ear FSM semantics.
//
// Typical usage is via the high-level Device wrapper:
//
//	dev, _ := devices.NewDevice(devices.DeviceOptions{ ... })
//	cfg := dev.NewFingerprint(devices.FingerprintOverrides{
//	    Behaviour: &devices.BehaviourOptions{
//	        Enabled:  true,
//	        Duration: 6 * time.Second,
//	        Activity: behaviour.ActivityTyping,
//	    },
//	})
//
// Simulate can also be called directly when you already have a
// FingerprintConfig and just want the raw `behaviour_results` dict:
//
//	raw := behaviour.Simulate(behaviour.SimulateOptions{
//	    Duration: 5 * time.Second,
//	    Seed:     42,
//	    Activity: behaviour.ActivityIdle,
//	})
//	cfg.BehaviourResults = &seonsdk.BehaviourData{RawResults: raw}
//
// Every exported type in this package is pinned byte-for-byte to a class,
// method, or function in SeonSDK.framework 5.6.3 — deviations are called out
// inline with the IDA address they were verified against. Noise-model
// constants in sample_gen.go are intentionally conservative pending
// real-device calibration via frida/capture.js.
package behaviour
